  "seo_lead_name" text,
  "agency_value" numeric,
  "client_priority" text,
  "campaign_type" text,
  "campaign_start_date" date,
  "total_link_kpi" integer,
  "total_links_achieved" integer,
  "monthly_rate" numeric,
  "monthly_hours" numeric,
  "is_active" boolean default true,
  "report_status" text,
  "last_report_date" date,
  "last_invoice_date" date,
  "created_at" timestamp with time zone default now(),
  "updated_at" timestamp with time zone default now(),
  "group_name" text,
  "region" text,
  "niche" text,
  "contract_length" text,
  "total_sprints" integer default 0,
  "active_sprints" integer default 0,
  "completed_sprints" integer default 0,
  "total_hours_used" numeric default 0,
  "total_hours_allocated" numeric,
  "overall_utilization_percent" numeric,
  "total_contract_revenue" numeric,
  "billable_contract_value" numeric,
  "avg_billable_rate" numeric,
  "at_risk_sprint_count" integer default 0,
  "behind_sprint_count" integer default 0,
  "metrics_last_calculated_at" timestamp with time zone,
  "has_incomplete_tracking" boolean default false,
  "is_quarterly_rate" boolean default false
);
create table public.sprints (
  "id" uuid default extensions.uuid_generate_v4() not null,
  "client_id" uuid not null,
  "monday_subitem_id" bigint not null,
  "name" text not null,
  "sprint_number" integer,
  "sprint_label" text,
  "start_date" date not null,
  "end_date" date not null,
  "kpi_target" integer not null,
  "kpi_achieved" integer default 0,
  "monthly_rate" numeric,
  "status" text default 'active'::text,
  "created_at" timestamp with time zone default now(),
  "updated_at" timestamp with time zone default now(),
  "hours_used" numeric default 0,
  "hours_allocated" numeric,
  "hours_utilization_percent" numeric,
  "billable_rate" numeric,
  "sprint_revenue" numeric,
  "kpi_progress_percent" numeric,
  "kpi_efficiency" numeric,
  "time_elapsed_percent" numeric,
  "days_remaining" integer,
  "health_status" text,
  "metrics_last_calculated_at" timestamp with time zone,
  "tracking_status" tracking_status_type default 'pending'::tracking_status_type
);
create table public.sync_logs (
  "id" uuid default extensions.uuid_generate_v4() not null,
  "source" text not null,
  "sync_start" timestamp with time zone not null,
  "sync_end" timestamp with time zone,
  "status" text not null,
  "records_synced" integer default 0,
  "error_message" text,
  "created_at" timestamp with time zone default now()
);
create table public.time_entries (
  "id" uuid default extensions.uuid_generate_v4() not null,
  "clockify_id" text not null,
  "sprint_id" uuid,
