CREATE OR REPLACE FUNCTION public.auth_email()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT email FROM auth.users WHERE id = auth.uid();
$function$;

CREATE OR REPLACE FUNCTION public.auto_set_sprint_status()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  -- Auto-set status based on dates
  IF NEW.end_date < CURRENT_DATE THEN
    NEW.status := 'completed';
  ELSIF NEW.start_date > CURRENT_DATE THEN
    NEW.status := 'pending';
  ELSE
    NEW.status := 'active';
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.calculate_billable_rate(p_sprint_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_monthly_rate NUMERIC;
    v_hours_used NUMERIC;
BEGIN
    SELECT
        s.monthly_rate,  -- Use sprint-level rate!
        COALESCE(SUM(te.hours), 0)
    INTO
        v_monthly_rate,
        v_hours_used
    FROM sprints s
    LEFT JOIN time_entries te ON te.sprint_id = s.id
    WHERE s.id = p_sprint_id
    GROUP BY s.monthly_rate;

    IF v_hours_used > 0 AND v_monthly_rate IS NOT NULL THEN
        -- Monthly Rate * 3 months / hours used
        RETURN (v_monthly_rate * 3) / v_hours_used;
    END IF;

    RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.calculate_hours_utilization(p_sprint_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    v_monthly_hours NUMERIC;
    v_hours_used NUMERIC;
BEGIN
    SELECT
        c.monthly_hours,
        COALESCE(SUM(te.hours), 0)
    INTO
        v_monthly_hours,
        v_hours_used
    FROM sprints s
    JOIN clients c ON s.client_id = c.id
    LEFT JOIN time_entries te ON te.sprint_id = s.id
    WHERE s.id = p_sprint_id
    GROUP BY c.monthly_hours;

    IF v_monthly_hours IS NOT NULL AND v_monthly_hours > 0 THEN
        -- (Hours used / (Monthly hours * 3)) * 100
        RETURN (v_hours_used / (v_monthly_hours * 3)) * 100;
    END IF;

    RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.calculate_sprint_health(p_sprint_id uuid)
 RETURNS text
 LANGUAGE plpgsql
 STABLE
AS $function$

DECLARE

    v_start_date DATE;

    v_end_date DATE;

    v_kpi_target INTEGER;

    v_kpi_achieved INTEGER;

    v_monthly_hours NUMERIC;

    v_hours_used NUMERIC;

    v_days_total INTEGER;

    v_days_elapsed INTEGER;

    v_percent_time NUMERIC;

    v_percent_kpi NUMERIC;

    v_percent_hours NUMERIC;

BEGIN

    -- Get sprint and client data

    SELECT

        s.start_date,

        s.end_date,

        s.kpi_target,

        s.kpi_achieved,

        c.monthly_hours,

        COALESCE(SUM(te.hours), 0)

    INTO

        v_start_date,

        v_end_date,

        v_kpi_target,

        v_kpi_achieved,

        v_monthly_hours,

        v_hours_used

    FROM sprints s

    JOIN clients c ON s.client_id = c.id

    LEFT JOIN time_entries te ON te.sprint_id = s.id

    WHERE s.id = p_sprint_id

    GROUP BY s.start_date, s.end_date, s.kpi_target, s.kpi_achieved, c.monthly_hours;

    
    -- NEW: Return NULL if sprint hasn't started yet
    IF v_start_date > CURRENT_DATE THEN
        RETURN NULL;
    END IF;

    -- Calculate percentages

    v_days_total := v_end_date - v_start_date;

    v_days_elapsed := GREATEST(0, CURRENT_DATE - v_start_date);

    v_percent_time := (v_days_elapsed::NUMERIC / NULLIF(v_days_total, 0)) * 100;

    v_percent_kpi := (v_kpi_achieved::NUMERIC / NULLIF(v_kpi_target, 0)) * 100;



    -- Calculate hours allocation (3 months = quarterly)

    IF v_monthly_hours IS NOT NULL THEN

        v_percent_hours := (v_hours_used / NULLIF(v_monthly_hours * 3, 0)) * 100;

    ELSE

        v_percent_hours := 0;

    END IF;



    -- Determine health status

    -- KPI Complete

    IF v_percent_kpi >= 100 THEN

        RETURN 'KPI Complete';

    END IF;



    -- At Risk: More than 80% time elapsed with less than 60% KPI

    IF v_percent_time > 80 AND v_percent_kpi < 60 THEN

        RETURN 'At Risk';

    END IF;



    -- Behind: Time/hours significantly ahead of KPI progress

    IF v_percent_time > v_percent_kpi + 15 THEN

        RETURN 'Behind';

    END IF;



    IF v_percent_hours > v_percent_kpi + 20 THEN

        RETURN 'Behind';

    END IF;



    -- Ahead: KPI progress ahead of timeline

    IF v_percent_kpi > v_percent_time + 10 THEN

        RETURN 'Ahead';

    END IF;



    -- Default: On Track

    RETURN 'On Track';

END;

$function$;

CREATE OR REPLACE FUNCTION public.check_email_domain()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.email NOT LIKE '%@studiohawk.com.au' THEN
    RAISE EXCEPTION 'Only @studiohawk.com.au email addresses are allowed';
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_sprint_hours(sprint_ids uuid[])
 RETURNS TABLE(sprint_id uuid, total_hours numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    te.sprint_id,
    COALESCE(SUM(te.hours), 0) as total_hours
  FROM time_entries te
  WHERE te.sprint_id = ANY(sprint_ids)
  GROUP BY te.sprint_id;
$function$;

CREATE OR REPLACE FUNCTION public.get_time_tracking_analytics()
 RETURNS TABLE(task_category text, dpr_lead_id uuid, sprint_count bigint, total_hours numeric, avg_hours numeric)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT
        INITCAP(COALESCE(te.task_category, 'Uncategorized')) as task_category,
        c.dpr_lead_id,
        COUNT(DISTINCT te.sprint_id) as sprint_count,
        SUM(te.hours) as total_hours,
        ROUND(SUM(te.hours)::numeric / COUNT(DISTINCT te.sprint_id), 1) as avg_hours
    FROM time_entries te
    JOIN sprints s ON te.sprint_id = s.id
    JOIN clients c ON s.client_id = c.id
    WHERE
        ((SELECT public.is_current_user_admin()) OR (SELECT auth.role()) = 'service_role')
        AND te.sprint_id IS NOT NULL
        AND s.status = 'completed'
        AND s.tracking_status = 'fully_tracked'
        AND c.dpr_lead_id IS NOT NULL
    GROUP BY INITCAP(COALESCE(te.task_category, 'Uncategorized')), c.dpr_lead_id
    ORDER BY task_category;
$function$;

CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Insert into public.users, extracting name from OAuth metadata
  INSERT INTO public.users (
    id,
    email,
    name,
    is_admin,
    is_dpr_lead,
    is_active,
    created_at,
    updated_at
  )
  VALUES (
    NEW.id,  -- Use auth.users.id as primary key for direct reference
    NEW.email,
    COALESCE(
      NEW.raw_user_meta_data->>'full_name',
      NEW.raw_user_meta_data->>'name',
      split_part(NEW.email, '@', 1)  -- Fallback to email prefix
    ),
    false,  -- New users are not admin by default
    false,  -- New users are not DPR lead by default
    true,   -- New users are active
    NOW(),
    NOW()
  )
  ON CONFLICT (email) DO UPDATE SET
    -- Update name if it was auto-generated and we now have a real name
    name = CASE
      WHEN public.users.name = split_part(public.users.email, '@', 1)
        AND EXCLUDED.name != split_part(EXCLUDED.email, '@', 1)
      THEN EXCLUDED.name
      ELSE public.users.name
    END,
    updated_at = NOW();
  
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.is_admin(user_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT is_admin FROM users WHERE id = user_id;
$function$;

CREATE OR REPLACE FUNCTION public.is_current_user_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (SELECT is_admin FROM users WHERE email = auth_email()),
    FALSE
  );
$function$;

CREATE OR REPLACE FUNCTION public.update_updated_at_column()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.validate_dpr_support_ids()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Check if all IDs in dpr_support_ids array exist in users table
  IF NEW.dpr_support_ids IS NOT NULL THEN
    IF EXISTS (
      SELECT 1 FROM UNNEST(NEW.dpr_support_ids) AS uid
      WHERE uid NOT IN (SELECT id FROM public.users)
    ) THEN
      RAISE EXCEPTION 'Invalid user ID in dpr_support_ids array';
    END IF;
  END IF;
  
  RETURN NEW;
END;
$function$;

CREATE TRIGGER update_clients_updated_at BEFORE UPDATE ON public.clients FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
CREATE TRIGGER validate_dpr_support_ids_trigger BEFORE INSERT OR UPDATE OF dpr_support_ids ON public.clients FOR EACH ROW EXECUTE FUNCTION validate_dpr_support_ids();
CREATE TRIGGER set_sprint_status_on_insert_update BEFORE INSERT OR UPDATE OF start_date, end_date ON public.sprints FOR EACH ROW EXECUTE FUNCTION auto_set_sprint_status();
CREATE TRIGGER trigger_auto_set_sprint_status BEFORE INSERT OR UPDATE OF start_date, end_date ON public.sprints FOR EACH ROW EXECUTE FUNCTION auto_set_sprint_status();
CREATE TRIGGER update_sprints_updated_at BEFORE UPDATE ON public.sprints FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
CREATE TRIGGER update_time_entries_updated_at BEFORE UPDATE ON public.time_entries FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();
CREATE TRIGGER check_email_domain_trigger BEFORE INSERT OR UPDATE ON auth.users FOR EACH ROW EXECUTE FUNCTION check_email_domain();
CREATE TRIGGER on_auth_user_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION handle_new_user();
CREATE TRIGGER update_users_updated_at BEFORE UPDATE ON public.users FOR EACH ROW EXECUTE FUNCTION update_updated_at_column();

