create policy "clients_select_admin" on public.clients as permissive for select to public using (is_current_user_admin());
create policy "clients_select_all_authenticated" on public.clients as permissive for select to authenticated using (true);
create policy "sprints_select_admin" on public.sprints as permissive for select to public using (is_current_user_admin());
create policy "sprints_select_all_authenticated" on public.sprints as permissive for select to authenticated using (true);
create policy "sync_logs_select_admin" on public.sync_logs as permissive for select to public using (is_current_user_admin());
create policy "time_entries_select_admin" on public.time_entries as permissive for select to public using (is_current_user_admin());
create policy "time_entries_select_assigned" on public.time_entries as permissive for select to public using ((EXISTS ( SELECT 1
   FROM (sprints
     JOIN clients ON ((clients.id = sprints.client_id)))
  WHERE ((sprints.id = time_entries.sprint_id) AND (clients.dpr_lead_id IN ( SELECT users.id
           FROM users
          WHERE (users.email = auth_email())))))));
create policy "time_entries_select_own" on public.time_entries as permissive for select to public using ((user_id IN ( SELECT users.id
   FROM users
  WHERE (users.email = auth_email()))));
create policy "users_select_admin" on public.users as permissive for select to public using (is_current_user_admin());
create policy "users_select_own" on public.users as permissive for select to public using ((email = auth_email()));

