-- Scheduled jobs (requires pg_cron and pg_net; HTTP jobs read the
-- 'cron_secret' Vault secret, which must be created separately).
do $cron$ begin if exists (select 1 from pg_extension where extname = 'pg_cron') then
  perform cron.schedule('calculate-all-metrics-evening', '0 18 * * *', $cmd$SELECT net.http_post(url := 'https://ylnrkfpchrzvuhqrnwco.supabase.co/functions/v1/calculate-all-metrics', headers := jsonb_build_object('Authorization', 'Bearer ' || (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'cron_secret'), 'Content-Type', 'application/json'), body := '{"trigger": "cron_evening", "skipReports": true}'::jsonb) AS request_id;$cmd$);
  perform cron.schedule('calculate-all-metrics-morning', '0 6 * * *', $cmd$SELECT net.http_post(url := 'https://ylnrkfpchrzvuhqrnwco.supabase.co/functions/v1/calculate-all-metrics', headers := jsonb_build_object('Authorization', 'Bearer ' || (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'cron_secret'), 'Content-Type', 'application/json'), body := '{"trigger": "cron_morning", "skipReports": true}'::jsonb) AS request_id;$cmd$);
  perform cron.schedule('sync-clockify-daily', '0 18 * * *', $cmd$SELECT net.http_post(url := 'https://ylnrkfpchrzvuhqrnwco.supabase.co/functions/v1/sync-clockify', headers := jsonb_build_object('Authorization', 'Bearer ' || (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'cron_secret'), 'Content-Type', 'application/json'), body := '{"days_back": 7}'::jsonb) AS request_id;$cmd$);
  perform cron.schedule('sync-monday-daily', '0 3 * * *', $cmd$SELECT net.http_post(url := 'https://ylnrkfpchrzvuhqrnwco.supabase.co/functions/v1/sync-monday', headers := jsonb_build_object('Authorization', 'Bearer ' || (SELECT decrypted_secret FROM vault.decrypted_secrets WHERE name = 'cron_secret'), 'Content-Type', 'application/json'), body := '{}'::jsonb) AS request_id;$cmd$);
  perform cron.schedule('update-sprint-statuses-daily', '5 0 * * *', $cmd$-- Update sprints to completed status
  UPDATE sprints
  SET status = 'completed'
  WHERE end_date < CURRENT_DATE
    AND status != 'completed';

  -- Update sprints to active status
  UPDATE sprints
  SET status = 'active'
  WHERE start_date <= CURRENT_DATE
    AND end_date >= CURRENT_DATE
    AND status NOT IN ('active', 'cancelled');

  -- Update sprints to pending status
  UPDATE sprints
  SET status = 'pending'
  WHERE start_date > CURRENT_DATE
    AND status != 'pending';$cmd$);
end if; end $cron$;
